Response charge(Request req) {
    for (int attempt = 0; attempt < 3; attempt++) {
        try {
            String body = json({
                "amount":   req.amount,
                "currency": req.currency,
                "customer": req.customerId
            });
            return http.post("/v1/charges", body, timeout_ms(2000));
        } catch (TimeoutException e) {
            log.warn("charge timed out, retrying", attempt);
            sleep(backoff(attempt));
        }
    }
    throw new ChargeFailedException("gave up after 3 attempts");
}
